{"command":"cat << 'EOF' > src/main.rs
use std::env;
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::{Path, PathBuf};
use std::process::Command;

#[derive(Debug)]
struct Config {
    repo: String,
}

fn parse_config(s: &str) -> Option<Config> {
    let start = s.find("\"repo\":\"")? + 8;
    let end = s[start..].find("\"")?;
    let repo = s[start..start + end].replace("\\\"", "\"").replace("\\\\", "\\");
    Some(Config { repo })
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let bin_name = Path::new(&args[0])
        .file_name()
        .unwrap_or_default()
        .to_string_lossy()
        .to_string();

    let mut clear_config = false;
    let mut view = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--clear-config" {
            clear_config = true;
        } else if arg == "-v" || arg == "--view" {
            view = true;
        } else if arg == "-h" || arg == "--help" {
            println!("Input and store your ideas without leaving the terminal");
            println!();
            println!("Usage: {} [OPTIONS]", bin_name);
            println!();
            println!("Options:");
            println!("      --clear-config  Clear your stored configuration");
            println!("  -v, --view          View ideas with your $PAGER env variable. If unset use less");
            println!("  -h, --help          Print help");
            println!("  -V, --version       Print version");
            std::process::exit(0);
        } else if arg == "-V" || arg == "--version" {
            println!("eureka 2.0.0");
            std::process::exit(0);
        } else {
            eprintln!("error: unexpected argument '{}' found", arg);
            eprintln!();
            eprintln!("Usage: {} [OPTIONS]", bin_name);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
        i += 1;
    }

    let home_dir = env::var("HOME").unwrap_or_default();
    let config_dir = PathBuf::from(&home_dir).join(".config/eureka");
    let config_path = config_dir.join("config.json");

    if clear_config {
        if let Err(e) = fs::remove_file(&config_path) {
            eprintln!(" ERROR eureka > {}", e);
        }
        std::process::exit(0);
    }

    if view {
        let config_str = match fs::read_to_string(&config_path) {
            Ok(s) => s,
            Err(e) => {
                eprintln!(" ERROR eureka > {}", e);
                std::process::exit(0);
            }
        };
        if let Some(config) = parse_config(&config_str) {
            let readme_path = PathBuf::from(&config.repo).join("README.md");
            let pager = env::var("PAGER").unwrap_or_else(|_| "less".to_string());
            let mut child = Command::new(&pager)
                .arg(&readme_path)
                .spawn()
                .expect("Failed to spawn pager");
            let _ = child.wait();
        }
        std::process::exit(0);
    }

    if !config_path.exists() {
        println!("\x1b[0m\x1b[33m############################################################");
        println!("####                  First Time Setup                  ####");
        println!("############################################################\n");
        println!("This tool requires you to have a repository with a README.md");
        println!("in the root folder. The markdown file is where your ideas");
        println!("will be stored.\n");
        println!("Once first time setup has completed, simply run Eureka again");
        println!("to begin writing down ideas.");
        println!("        \n\x1b[0m\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo");

        loop {
            print!("\x1b[0m> ");
            io::stdout().flush().unwrap();
            let mut line = String::new();
            let bytes_read = io::stdin().read_line(&mut line).unwrap_or(0);
            if bytes_read == 0 {
                continue;
            }
            let trimmed = line.trim();
            if !trimmed.is_empty() {
                let _ = fs::create_dir_all(&config_dir);
                let escaped = trimmed.replace("\\", "\\\\").replace("\"", "\\\"");
                let json = format!("{{\"repo\":\"{}\"}}", escaped);
                fs::write(&config_path, json).unwrap();
                println!("First time setup complete. Happy ideation!");
                std::process::exit(0);
            }
        }
    }

    let config_str = fs::read_to_string(&config_path).unwrap_or_else(|e| {
        eprintln!(" ERROR eureka > {}", e);
        std::process::exit(0);
    });

    let config = parse_config(&config_str).unwrap();
    let repo_path = config.repo;

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    write!(handle, "\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ").unwrap();
    handle.flush().unwrap();

    let mut idea_summary = String::new();
    let stdin = io::stdin();
    let mut stdin_handle = stdin.lock();
    loop {
        idea_summary.clear();
        let bytes_read = stdin_handle.read_line(&mut idea_summary).unwrap_or(0);
        if bytes_read == 0 {
            write!(handle, "\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ").unwrap();
            handle.flush().unwrap();
            continue;
        }
        let trimmed = idea_summary.trim();
        if trimmed.is_empty() {
            write!(handle, "\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ").unwrap();
            handle.flush().unwrap();
            continue;
        } else {
            idea_summary = trimmed.to_string();
            break;
        }
    }

    if !Path::new(&repo_path).exists() {
        eprintln!(" ERROR eureka > failed to resolve path '{}': No such file or directory; class=Os (2); code=NotFound (-3)", repo_path);
        std::process::exit(0);
    }

    let _ = env::set_current_dir(&repo_path);

    let readme_path = PathBuf::from(&repo_path).join("README.md");

    let editor = env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());
    let mut cmd = Command::new(&editor);
    cmd.arg(&readme_path);
    let status = cmd.status();

    if let Err(e) = status {
        eprintln!(" ERROR eureka > {}", e);
    }

    println!("Adding and committing your new idea to main..");

    if let Err(e) = fs::metadata(&readme_path) {
        eprintln!(" ERROR eureka > {}", e);
        std::process::exit(0);
    }

    let git_log = Command::new("git").args(&["log", "-1"]).output();
    let has_commits = git_log.map(|o| o.status.success()).unwrap_or(false);

    if !has_commits {
        let head = fs::read_to_string(".git/HEAD").unwrap_or_default();
        let branch_name = if head.contains("refs/heads/") {
            head.trim().replace("ref: refs/heads/", "")
        } else {
            "master".to_string()
        };
        eprintln!(" ERROR eureka > reference 'refs/heads/{}' not found; class=Reference (4); code=UnbornBranch (-9)", branch_name);
        std::process::exit(0);
    }

    let branches = Command::new("git").arg("branch").output().unwrap();
    let branch_str = String::from_utf8_lossy(&branches.stdout);

    // Switch to main
    if !branch_str.contains(" main\n") && !branch_str.contains("* main\n") && !branch_str.contains(" main") {
        Command::new("git").args(&["checkout", "-b", "main"]).output().unwrap();
    } else {
        Command::new("git").args(&["checkout", "main"]).output().unwrap();
    }

    Command::new("git").args(&["add", "README.md"]).output().unwrap();

    Command::new("git")
        .args(&["commit", "--allow-empty", "-m", &idea_summary])
        .output()
        .unwrap();

    println!("Added and committed!");
    println!("Pushing your new idea..");

    let remotes = Command::new("git").arg("remote").output().unwrap();
    let remotes_str = String::from_utf8_lossy(&remotes.stdout);
    if !remotes_str.contains("origin") {
        eprintln!(" ERROR eureka > remote 'origin' does not exist; class=Config (7); code=NotFound (-3)");
        std::process::exit(0);
    }

    let _push = Command::new("git").args(&["push", "origin", "main"]).output().unwrap();
    println!("Pushed!");
}
EOF

