                let escaped = trimmed.replace("\\", "\\\\").replace("\"", "\\\"");
                let json = format!("{{\"repo\":\"{}\"}}", escaped);
                fs::write(&config_path, json).unwrap();
                println!("First time setup complete. Happy ideation!");
                std::process::exit(0);
            }
        }
    }

    let config_str = fs::read_to_string(&config_path).unwrap_or_else(|e| {
        eprintln!(" ERROR eureka > {}", e);
        std::process::exit(0);
    });

    let config = parse_config(&config_str).unwrap();
    let repo_path = config.repo;

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    write!(handle, "\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ").unwrap();
    handle.flush().unwrap();

    let mut idea_summary = String::new();
    let stdin = io::stdin();
    let mut stdin_handle = stdin.lock();
    loop {
        idea_summary.clear();
        let bytes_read = stdin_handle.read_line(&mut idea_summary).unwrap_or(0);
        if bytes_read == 0 {
            write!(handle, "\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ").unwrap();
            handle.flush().unwrap();
            continue;
        }
        let trimmed = idea_summary.trim();
        if trimmed.is_empty() {
            write!(handle, "\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ").unwrap();
            handle.flush().unwrap();
            continue;
        } else {
            idea_summary = trimmed.to_string();
            break;
        }
    }

    if !Path::new(&repo_path).exists() {
        eprintln!(" ERROR eureka > failed to resolve path '{}': No such file or directory; class=Os (2); code=NotFound (-3)", repo_path);
        std::process::exit(0);
    }

    let _ = env::set_current_dir(&repo_path);

    let readme_path = PathBuf::from(&repo_path).join("README.md");

    let editor = env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());
    let mut cmd = Command::new(&editor);
    cmd.arg(&readme_path);
    let status = cmd.status();

    if let Err(e) = status {
        eprintln!(" ERROR eureka > {}", e);
    }

    println!("Adding and committing your new idea to main..");

    if let Err(e) = fs::metadata(&readme_path) {
        eprintln!(" ERROR eureka > {}", e);
        std::process::exit(0);
    }

    let git_log = Command::new("git").args(&["log", "-1"]).output();
    let has_commits = git_log.map(|o| o.status.success()).unwrap_or(false);

    if !has_commits {
        let head = fs::read_to_string(".git/HEAD").unwrap_or_default();
        let branch_name = if head.contains("refs/heads/") {
            head.trim().replace("ref: refs/heads/", "")
        } else {
            "master".to_string()
        };
        eprintln!(" ERROR eureka > reference 'refs/heads/{}' not found; class=Reference (4); code=UnbornBranch (-9)", branch_name);
        std::process::exit(0);
    }

    let branches = Command::new("git").arg("branch").output().unwrap();
    let branch_str = String::from_utf8_lossy(&branches.stdout);

    // Switch to main
    if !branch_str.contains(" main\n") && !branch_str.contains("* main\n") && !branch_str.contains(" main") {
        Command::new("git").args(&["checkout", "-b", "main"]).output().unwrap();
    } else {
        Command::new("git").args(&["checkout", "main"]).output().unwrap();
    }

    Command::new("git").args(&["add", "README.md"]).output().unwrap();

    Command::new("git")
        .args(&["commit", "--allow-empty", "-m", &idea_summary])
        .output()
        .unwrap();

    println!("Added and committed!");
    println!("Pushing your new idea..");

    let remotes = Command::new("git").arg("remote").output().unwrap();
    let remotes_str = String::from_utf8_lossy(&remotes.stdout);
    if !remotes_str.contains("origin") {
        eprintln!(" ERROR eureka > remote 'origin' does not exist; class=Config (7); code=NotFound (-3)");
        std::process::exit(0);
    }

    let _push = Command::new("git").args(&["push", "origin", "main"]).output().unwrap();
    println!("Pushed!");
}
